double gjendjafund = 0.0;
double gjendjamb = 0.0;
double gjendjatotalemb = 0.0;


private void PageHeader_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

}

private void xrTableCell7_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
  if (GetCurrentColumnValue("Gjendja") != null)
            {
                e.Result = gjendjafund + double.Parse(GetCurrentColumnValue("Gjendja").ToString());
                e.Handled = true;
            }
}

private void xrTableCell7_SummaryReset(object sender, System.EventArgs e) {
 gjendjafund = 0;
}

private void xrTableCell7_SummaryRowChanged(object sender, System.EventArgs e) {
  if (GetCurrentColumnValue("VLERA") != null)
            {
                if (((GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToLower() == "derdhje") || (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToLower() == "arketim")) && (double.Parse(GetCurrentColumnValue("GJENDJEMBARTUR").ToString()) == 0))
                {
                    gjendjafund += double.Parse(GetCurrentColumnValue("VLERA").ToString());
                }
                else
                    gjendjafund -= double.Parse(GetCurrentColumnValue("VLERA").ToString());
            }
}  
private void xrTableCell9_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
XRLabel label = (XRLabel)sender;
XtraReport report = (XtraReport)label.Report;
string parameterPese = (string)report.Parameters["parameter5"].Value;

 if (GetCurrentColumnValue("GjendjaMB") != null)
            {
                if (parameterPese == "Po" && (GetCurrentColumnValue("MONEDHAKOD").ToString() != "LEK"))
                {
                    e.Result = gjendjamb + double.Parse(GetCurrentColumnValue("Gjendja").ToString()) * double.Parse(GetCurrentColumnValue("VLERAKURSIT").ToString());
                    gjendjatotalemb += gjendjamb + double.Parse(GetCurrentColumnValue("Gjendja").ToString()) * double.Parse(GetCurrentColumnValue("VLERAKURSIT").ToString());
                    e.Handled = true;
                }
                else
                {
                    e.Result = gjendjamb + double.Parse(GetCurrentColumnValue("GjendjaMB").ToString());
                    gjendjatotalemb += gjendjamb + double.Parse(GetCurrentColumnValue("GjendjaMB").ToString());
                    e.Handled = true;
                }
            }
}

private void xrTableCell9_SummaryReset(object sender, System.EventArgs e) {
 gjendjamb = 0;
}

private void xrTableCell9_SummaryRowChanged(object sender, System.EventArgs e) {
XRLabel label = (XRLabel)sender;
XtraReport report = (XtraReport)label.Report;
string parameterPese = (string)report.Parameters["parameter5"].Value;

if (GetCurrentColumnValue("VLERAMONADHABAZE") != null)
            {
                if (parameterPese == "Po" && (GetCurrentColumnValue("MONEDHAKOD").ToString() != "LEK"))
                {
                    if (((GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToLower() == "derdhje") || (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToLower() == "arketim")) && (double.Parse(GetCurrentColumnValue("GJENDJEMBARTUR").ToString()) == 0))
                        gjendjamb += double.Parse(GetCurrentColumnValue("VLERA").ToString()) * double.Parse(GetCurrentColumnValue("VLERAKURSIT").ToString());
                    else
                        gjendjamb -= double.Parse(GetCurrentColumnValue("VLERA").ToString()) * double.Parse(GetCurrentColumnValue("VLERAKURSIT").ToString());
                }
                else
                {
                    if (((GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToLower() == "derdhje") || (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToLower() == "arketim")) && (double.Parse(GetCurrentColumnValue("GJENDJEMBARTUR").ToString()) == 0))
                        gjendjamb += double.Parse(GetCurrentColumnValue("VLERAMONADHABAZE").ToString());
                    else
                        gjendjamb -= double.Parse(GetCurrentColumnValue("VLERAMONADHABAZE").ToString());
                }
            }
}

private void xrLabel8_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {

XRLabel label = (XRLabel)sender;
XtraReport report = (XtraReport)label.Report;
string parameterPese = (string)report.Parameters["parameter5"].Value;
            if (GetCurrentColumnValue("VLERAMONADHABAZE") != null)
            {
                if (parameterPese == "Po" && (GetCurrentColumnValue("MONEDHAKOD").ToString() != "LEK"))
                {

                    e.Result = gjendjatotalemb - double.Parse(GetCurrentColumnValue("Gjendja").ToString()) * double.Parse(GetCurrentColumnValue("VLERAKURSIT").ToString());
                    e.Handled = true;
                }
                else
                {
                    e.Result = gjendjatotalemb - double.Parse(GetCurrentColumnValue("GjendjaMB").ToString());
                    e.Handled = true;
                }
            }
}

int row = 0;
private void GroupHeader1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e)
{ 
if (row % 2 == 0) 
GroupHeader1.Styles.Style = (DevExpress.XtraReports.UI.XRControlStyle)StyleSheet["PermbajtjaRaportEven"];
 else GroupHeader1.Styles.Style = (DevExpress.XtraReports.UI.XRControlStyle)StyleSheet["PermbajtjaRaportOdd"];
 row++; 
}
